! qty_ok abc || { echo "qty_ok abc accepted"; fail=1; }
t=$(mktemp); printf '# h\n2026-10-01\tA-100\t30\tIN\tPO-1\n2026-10-02\tA-100\t12\tOUT\tSO-1\n2026-10-02\tB-010\t5\tIN\tPO-2\n' > "$t"
